scenarios.source:
// Richards: Martin Richards' OS task-scheduler simulation, ported from the
// Octane / Are We Fast Yet version (BSD / MIT). Idle, worker, handler and
// device tasks pass packets through a priority scheduler. Exercises interface
// dispatch, nullable object links, field mutation and bit operations.
// 50 runs at COUNT = 1000; each must end with queue_count 2322, hold_count 928.
class Packet {
  link: Packet?
  id: int
  kind: int
  a1: int
  a2: int[]
}
function packet(link: Packet?, id: int, kind: int) -> Packet {
  Packet { link: link, id: id, kind: kind, a1: 0, a2: [0, 0, 0, 0] }
}
function add_to(p: Packet, queue: Packet?) -> Packet {
  p.link = null;
  if (queue == null) { return p; }
  let peek: Packet = queue;
  while (true) {
    let next = peek.link;
    if (next == null) { break; }
    peek = next;
  }
  peek.link = p;
  queue
}
interface Task {
  function run(self, s: Scheduler, packet: Packet?) -> Tcb? throws never
}
class Tcb {
  link: Tcb?
  id: int
  priority: int
  queue: Packet?
  task: Task
  state: int
}
function tcb_run(t: Tcb, s: Scheduler) -> Tcb? {
  let p: Packet? = null;
  if (t.state == 3) {
    let q = t.queue;
    if (q != null) {
      p = q;
      t.queue = q.link;
      if (t.queue == null) { t.state = 0; } else { t.state = 1; }
    }
  }
  t.task.run(s, p)
}
function check_priority_add(t: Tcb, task: Tcb, p: Packet) -> Tcb {
  if (t.queue == null) {
    t.queue = p;
    t.state = t.state | 1;
    if (t.priority > task.priority) { return t; }
  } else {
    t.queue = add_to(p, t.queue);
  }
  task
}
function held_or_suspended(t: Tcb) -> bool {
  (t.state & 4) != 0 || t.state == 2
}
class Scheduler {
  queue_count: int
  hold_count: int
  blocks: (Tcb?)[]
  list: Tcb?
  current: Tcb?
  current_id: int
}
function add_task(s: Scheduler, id: int, priority: int, queue: Packet?, task: Task) -> Tcb {
  let state = if (queue == null) { 2 } else { 3 };
  let t = Tcb { link: s.list, id: id, priority: priority, queue: queue, task: task, state: state };
  s.current = t;
  s.list = t;
  s.blocks[id] = t;
  t
}
function release(s: Scheduler, id: int) -> Tcb? {
  let t = s.blocks[id];
  if (t == null) { return null; }
  t.state = t.state & -5;
  let c = s.current;
  if (c == null || t.priority > c.priority) { return t; }
  c
}
function hold_current(s: Scheduler) -> Tcb? {
  s.hold_count += 1;
  let c = s.current;
  if (c == null) { return null; }
  c.state = c.state | 4;
  c.link
}
function suspend_current(s: Scheduler) -> Tcb? {
  let c = s.current;
  if (c == null) { return null; }
  c.state = c.state | 2;
  c
}
function enqueue(s: Scheduler, p: Packet) -> Tcb? {
  let t = s.blocks[p.id];
  if (t == null) { return null; }
  let c = s.current;
  if (c == null) { return null; }
  s.queue_count += 1;
  p.link = null;
  p.id = s.current_id;
  check_priority_add(t, c, p)
}
class IdleTask {
  v1: int
  count: int
  implements Task {
    function run(self, s: Scheduler, packet: Packet?) -> Tcb? {
      self.count -= 1;
      if (self.count == 0) { return hold_current(s); }
      if ((self.v1 & 1) == 0) {
        self.v1 = self.v1 >> 1;
        return release(s, 4);
      }
      self.v1 = (self.v1 >> 1) ^ 53256;
      release(s, 5)
    }
  }
}
class DeviceTask {
  v1: Packet?
  implements Task {
    function run(self, s: Scheduler, packet: Packet?) -> Tcb? {
      if (packet == null) {
        let v = self.v1;
        if (v == null) { return suspend_current(s); }
        self.v1 = null;
        return enqueue(s, v);
      }
      self.v1 = packet;
      hold_current(s)
    }
  }
}
class WorkerTask {
  v1: int
  v2: int
  implements Task {
    function run(self, s: Scheduler, packet: Packet?) -> Tcb? {
      if (packet == null) { return suspend_current(s); }
      if (self.v1 == 2) { self.v1 = 3; } else { self.v1 = 2; }
      packet.id = self.v1;
      packet.a1 = 0;
      for (let i = 0; i < 4; i += 1) {
        self.v2 += 1;
        if (self.v2 > 26) { self.v2 = 1; }
        packet.a2[i] = self.v2;
      }
      enqueue(s, packet)
    }
  }
}
class HandlerTask {
  v1: Packet?
  v2: Packet?
  implements Task {
    function run(self, s: Scheduler, packet: Packet?) -> Tcb? {
      if (packet != null) {
        if (packet.kind == 1) { self.v1 = add_to(packet, self.v1); }
        else { self.v2 = add_to(packet, self.v2); }
      }
      let w = self.v1;
      if (w != null) {
        let count = w.a1;
        if (count < 4) {
          let d = self.v2;
          if (d != null) {
            self.v2 = d.link;
            d.a1 = w.a2[count];
            w.a1 = count + 1;
            return enqueue(s, d);
          }
        } else {
          self.v1 = w.link;
          return enqueue(s, w);
        }
      }
      suspend_current(s)
    }
  }
}
function richards() -> int {
  let s = Scheduler { queue_count: 0, hold_count: 0, blocks: [null, null, null, null, null, null], list: null, current: null, current_id: 0 };
  let idle = add_task(s, 0, 0, null, IdleTask { v1: 1, count: 1000 });
  idle.state = 0;
  let q = packet(null, 1, 1);
  q = packet(q, 1, 1);
  add_task(s, 1, 1000, q, WorkerTask { v1: 2, v2: 0 });
  q = packet(null, 4, 0);
  q = packet(q, 4, 0);
  q = packet(q, 4, 0);
  add_task(s, 2, 2000, q, HandlerTask { v1: null, v2: null });
  q = packet(null, 5, 0);
  q = packet(q, 5, 0);
  q = packet(q, 5, 0);
  add_task(s, 3, 3000, q, HandlerTask { v1: null, v2: null });
  add_task(s, 4, 4000, null, DeviceTask { v1: null });
  add_task(s, 5, 5000, null, DeviceTask { v1: null });
  s.current = s.list;
  while (true) {
    let c = s.current;
    if (c == null) { break; }
    if (held_or_suspended(c)) {
      s.current = c.link;
    } else {
      s.current_id = c.id;
      s.current = tcb_run(c, s);
    }
  }
  s.queue_count * 10000 + s.hold_count
}
function main() -> int {
  let total = 0;
  for (let i = 0; i < 50; i += 1) { total += richards(); }
  total
}

// A hand-written recursive-descent JSON parser in the style of Are We Fast
// Yet's Json benchmark (a port of minimal-json, MIT): character scanning,
// string slicing and escape decoding, building a tree of union-typed values,
// and errors thrown and caught for malformed input. Parses a ~25 KB document
// 15 times plus six malformed inputs, then walks the trees.
class JObject { names: string[], values: JValue[] }
class JArray { values: JValue[] }
class JString { value: string }
class JNumber { text: string }
class JLiteral { kind: int }
type JValue = JObject | JArray | JString | JNumber | JLiteral
class ParseError { message: string, offset: int }
class Parser { text: string, cps: int[], pos: int }
function current(p: Parser) -> int {
  if (p.pos < p.cps.length()) { return p.cps[p.pos]; }
  return -1;
}
function fail(p: Parser, message: string) -> int {
  throw ParseError { message: message, offset: p.pos };
}
function skip_ws(p: Parser) -> int {
  while (true) {
    let c = current(p);
    if (c != 32 && c != 9 && c != 10 && c != 13) { break; }
    p.pos += 1;
  }
  0
}
function read_char(p: Parser, c: int) -> bool {
  if (current(p) != c) { return false; }
  p.pos += 1;
  true
}
function expect(p: Parser, c: int, what: string) -> int {
  if (!read_char(p, c)) { fail(p, "expected " + what); }
  0
}
function is_digit(c: int) -> bool { c >= 48 && c <= 57 }
function read_digits(p: Parser) -> int {
  if (!is_digit(current(p))) { fail(p, "expected digit"); }
  while (is_digit(current(p))) { p.pos += 1; }
  0
}
function read_number(p: Parser) -> JValue {
  let start = p.pos;
  read_char(p, 45);
  let first = current(p);
  read_digits(p);
  if (first == 48 && p.pos - start > 1 + (if (p.cps[start] == 45) { 1 } else { 0 })) {
    fail(p, "leading zero");
  }
  if (read_char(p, 46)) { read_digits(p); }
  if (read_char(p, 101) || read_char(p, 69)) {
    if (!read_char(p, 43)) { read_char(p, 45); }
    read_digits(p);
  }
  JNumber { text: p.text.slice(start, p.pos) }
}
function hex_value(p: Parser) -> int {
  let c = current(p);
  p.pos += 1;
  if (c >= 48 && c <= 57) { return c - 48; }
  if (c >= 97 && c <= 102) { return c - 87; }
  if (c >= 65 && c <= 70) { return c - 55; }
  fail(p, "bad hex digit")
}
function read_string(p: Parser) -> string {
  expect(p, 34, "string");
  let parts: string[] = [];
  let start = p.pos;
  while (true) {
    let c = current(p);
    if (c == 34) { break; }
    if (c < 0) { fail(p, "unterminated string"); }
    if (c == 92) {
      parts.push(p.text.slice(start, p.pos));
      p.pos += 1;
      let e = current(p);
      p.pos += 1;
      if (e == 34) { parts.push("\""); }
      else if (e == 92) { parts.push("\\"); }
      else if (e == 47) { parts.push("/"); }
      else if (e == 98) { parts.push(string.from_code_points([8])); }
      else if (e == 102) { parts.push(string.from_code_points([12])); }
      else if (e == 110) { parts.push("\n"); }
      else if (e == 114) { parts.push("\r"); }
      else if (e == 116) { parts.push("\t"); }
      else if (e == 117) {
        let cp = hex_value(p) * 4096 + hex_value(p) * 256 + hex_value(p) * 16 + hex_value(p);
        parts.push(string.from_code_points([cp]));
      } else { fail(p, "bad escape"); }
      start = p.pos;
    } else {
      p.pos += 1;
    }
  }
  parts.push(p.text.slice(start, p.pos));
  p.pos += 1;
  parts.join("")
}
function read_literal(p: Parser, word: string, kind: int) -> JValue {
  for (let c in word.to_code_points()) { expect(p, c, word); }
  JLiteral { kind: kind }
}
function read_value(p: Parser) -> JValue {
  let c = current(p);
  if (c == 123) {
    p.pos += 1;
    let obj = JObject { names: [], values: [] };
    skip_ws(p);
    if (read_char(p, 125)) { return obj; }
    while (true) {
      skip_ws(p);
      obj.names.push(read_string(p));
      skip_ws(p);
      expect(p, 58, "':'");
      skip_ws(p);
      obj.values.push(read_value(p));
      skip_ws(p);
      if (!read_char(p, 44)) { break; }
    }
    expect(p, 125, "'}'");
    return obj;
  }
  if (c == 91) {
    p.pos += 1;
    let arr = JArray { values: [] };
    skip_ws(p);
    if (read_char(p, 93)) { return arr; }
    while (true) {
      skip_ws(p);
      arr.values.push(read_value(p));
      skip_ws(p);
      if (!read_char(p, 44)) { break; }
    }
    expect(p, 93, "']'");
    return arr;
  }
  if (c == 34) { return JString { value: read_string(p) }; }
  if (c == 116) { return read_literal(p, "true", 1); }
  if (c == 102) { return read_literal(p, "false", 2); }
  if (c == 110) { return read_literal(p, "null", 0); }
  if (c == 45 || is_digit(c)) { return read_number(p); }
  fail(p, "unexpected character");
  JLiteral { kind: 0 }
}
function parse(text: string) -> JValue {
  let p = Parser { text: text, cps: text.to_code_points(), pos: 0 };
  skip_ws(p);
  let v = read_value(p);
  skip_ws(p);
  if (p.pos != p.cps.length()) { fail(p, "trailing input"); }
  v
}
function walk(v: JValue) -> int {
  match (v) {
    JObject => {
      let h = v.names.length() * 7;
      for (let n in v.names) { h += n.length(); }
      for (let x in v.values) { h += walk(x); }
      h
    },
    JArray => {
      let h = 3;
      for (let x in v.values) { h += walk(x); }
      h
    },
    JString => 11 + v.value.length(),
    JNumber => 13 + v.text.length(),
    JLiteral => 17 + v.kind,
  }
}
// The input: 160 records exercising every JSON form, with escapes in strings
// and numbers in every shape, built from a seeded LCG.
function make_doc(n: int) -> string {
  let seed = 5;
  let records: string[] = [];
  for (let i = 0; i < n; i += 1) {
    seed = seed * 16807 % 2147483647;
    let tags: string[] = [];
    for (let k = 0; k < i % 5; k += 1) { tags.push("\"t" + (seed % (k + 3)).to_string() + "\""); }
    let sign = if (i % 3 == 0) { "-" } else { "" };
    let exp = if (i % 4 == 0) { "e+" + (i % 5).to_string() } else if (i % 4 == 1) { "E-" + (i % 3).to_string() } else { "" };
    let parent = if (i % 4 == 0) { (i / 4).to_string() } else { "null" };
    let active = if (i % 2 == 0) { "true" } else { "false" };
    records.push("{\"id\": " + i.to_string() + ", \"name\": \"user_" + (seed % 10007).to_string() + "\", \"score\": " + sign
      + (seed % 1000).to_string() + "." + (seed % 10).to_string() + exp + ", \"tags\": [" + tags.join(", ") + "], \"active\": " + active
      + ", \"parent\": " + parent + ", \"bio\": \"line " + i.to_string() + "\\nwith \\\"quotes\\\", a tab\\tand caf\\u00e9 \\u2603 / slash \\\\ back\""
      + ", \"nested\": {\"depth\": [{\"x\": [" + i.to_string() + ", [" + (i + 1).to_string() + ", {\"y\": null}]]}]}}");
  }
  "{\"records\": [\n  " + records.join(",\n  ") + "\n], \"count\": " + n.to_string() + ", \"ok\": true}"
}

function main() -> int {
  let doc = make_doc(160);
  let bad = ["{\"a\": tru}", "[1, 2", "{\"a\" 1}", "[01]", "\"unterminated", "{\"a\": -}"];
  let total = 0;
  for (let i = 0; i < 15; i += 1) {
    total += walk(parse(doc));
    for (let b in bad) {
      let r = parse(b) catch (e) { ParseError => JLiteral { kind: 1000 + e.offset } };
      total += walk(r);
    }
  }
  total
}

// An agent loop over recorded model responses, the shape of a BAML program
// around its LLM calls with the network removed: each response is decoded with
// typed JSON deserialize into a union of tool-call classes (string-literal
// discriminants, an optional field, a literal-union field), dispatched with
// match, and folded into per-conversation state (a map scratchpad and a message
// history). Malformed responses (truncated JSON, unknown tool, missing field)
// throw, are caught and retried; too many retries abandon the conversation
// with a custom error class. 300 conversations, 3 passes.
class Search { tool: "search", query: string, limit: int? }
class Calc { tool: "calc", op: "add" | "sub" | "mul", a: int, b: int }
class Finish { tool: "finish", answer: string, confidence: "low" | "medium" | "high" }
type Action = Search | Calc | Finish
class AgentState {
  scratch: map<string, int>
  history: string[]
  steps: int
  retries: int
  answer: string?
}
class AgentFailed { retries: int }
function fake_search(query: string, limit: int) -> int {
  let h = 0;
  for (let c in query.to_code_points()) { h = (h * 31 + c) % 1000003; }
  h % (limit * 100)
}
function step(state: AgentState, action: Action) -> bool {
  state.steps += 1;
  match (action) {
    Search => {
      let value = fake_search(action.query, action.limit ?? 10);
      state.scratch[action.query] = value;
      state.history.push("search:" + action.query + "=" + value.to_string());
      false
    },
    Calc => {
      let value = match (action.op) {
        "add" => action.a + action.b,
        "sub" => action.a - action.b,
        "mul" => action.a * action.b,
      };
      state.scratch["calc" + state.steps.to_string()] = value;
      state.history.push("calc:" + action.op + "=" + value.to_string());
      false
    },
    Finish => {
      state.answer = action.answer + "/" + action.confidence;
      state.history.push("finish");
      true
    },
  }
}
function run_conversation(turns: string[]) -> AgentState {
  let state = AgentState { scratch: {}, history: [], steps: 0, retries: 0, answer: null };
  for (let raw in turns) {
    let action: Action? = baml.json.decode<Action>(raw) catch (_) { let _ => null };
    if (action == null) {
      state.retries += 1;
      state.history.push("retry");
      if (state.retries > 2) { throw AgentFailed { retries: state.retries }; }
    } else {
      if (step(state, action)) { break; }
    }
  }
  state
}
// The recorded responses: 300 conversations of 2-7 tool calls ending in a
// finish, with truncated JSON, unknown tools and missing fields mixed in,
// built from a seeded LCG.
class Rng {
  seed: int
}

function draw(rng: Rng, n: int) -> int {
  rng.seed = rng.seed * 16807 % 2147483647;
  rng.seed % n
}

function conversations(count: int) -> string[][] {
  let rng = Rng { seed: 17 };
  let words = ["weather", "paris", "capital", "population", "rust", "python", "llm", "agent", "tokens", "latency"];
  let ops = ["add", "sub", "mul"];
  let levels = ["low", "medium", "high"];
  let convs: string[][] = [];
  for (let c = 0; c < count; c += 1) {
    let turns: string[] = [];
    let n = 2 + draw(rng, 6);
    for (let t = 0; t < n; t += 1) {
      let kind = draw(rng, 10);
      if (kind < 4) {
        let q: string[] = [];
        let m = 1 + draw(rng, 3);
        for (let k = 0; k < m; k += 1) { q.push(words[draw(rng, 10)]); }
        let r = "{\"tool\": \"search\", \"query\": \"" + q.join(" ") + "\"";
        if (draw(rng, 2) == 1) { r = r + ", \"limit\": " + (1 + draw(rng, 9)).to_string(); }
        turns.push(r + "}");
      } else if (kind < 7) {
        let op = ops[draw(rng, 3)];
        let a = draw(rng, 1000);
        let b = draw(rng, 1000);
        turns.push("{\"tool\": \"calc\", \"op\": \"" + op + "\", \"a\": " + a.to_string() + ", \"b\": " + b.to_string() + "}");
      } else if (kind == 7) {
        turns.push("{\"tool\": \"search\", \"query\": \"broken\"}".slice(0, 5 + draw(rng, 10)));
      } else if (kind == 8) {
        turns.push("{\"tool\": \"browse\", \"url\": \"http://x\"}");
      } else {
        turns.push("{\"tool\": \"calc\", \"op\": \"add\", \"a\": " + draw(rng, 10).to_string() + "}");
      }
    }
    let answer = draw(rng, 100000);
    turns.push("{\"tool\": \"finish\", \"answer\": \"answer " + answer.to_string() + "\", \"confidence\": \"" + levels[draw(rng, 3)] + "\"}");
    convs.push(turns);
  }
  convs
}

function main() -> int {
  let convs = conversations(300);
  let check = 0;
  for (let pass = 0; pass < 3; pass += 1) {
    for (let turns in convs) {
      let score = 0;
      let state = run_conversation(turns) catch (e) {
        AgentFailed => { score = 7 + e.retries; null }
      };
      if (state != null) {
        let total = 0;
        for (let v in state.scratch.values()) { total += v; }
        let answer = state.answer ?? "";
        score = state.steps * 1000 + state.retries * 100 + answer.length() + state.history.length() * 3 + (total % 9973 + 9973) % 9973;
      }
      check = (check * 31 + score) % 1000000007;
    }
  }
  check
}

// Bottom-up merge sort written in user code (ported from the native-bench
// merge_sort case): index reads and writes, branches and buffer swaps in tight
// loops over a 20,000-element int array, sorted from four input orders.
function lcg_values(n: int, seed0: int) -> int[] {
  let seed = seed0;
  let out: int[] = [];
  for (let i = 0; i < n; i += 1) {
    seed = seed * 16807 % 2147483647;
    out.push(seed % 100000);
  }
  out
}
function merge_sort(values: int[]) -> int[] {
  let a: int[] = [];
  let b: int[] = [];
  for (let value in values) { a.push(value); b.push(0); }
  let width = 1;
  let n = a.length();
  while (width < n) {
    let lo = 0;
    while (lo < n) {
      let mid = lo + width;
      if (mid > n) { mid = n; }
      let hi = lo + 2 * width;
      if (hi > n) { hi = n; }
      let i = lo;
      let j = mid;
      let k = lo;
      while (k < hi) {
        if (i < mid && (j >= hi || a[i] <= a[j])) {
          b[k] = a[i]; i += 1;
        } else { b[k] = a[j]; j += 1; }
        k += 1;
      }
      lo += 2 * width;
    }
    let tmp = a; a = b; b = tmp;
    width *= 2;
  }
  a
}
function checksum(xs: int[]) -> int {
  let h = 0;
  for (let i = 0; i < xs.length(); i += 1) {
    if (i > 0 && xs[i - 1] > xs[i]) { return -1; }
    h = (h * 31 + xs[i]) % 1000000007;
  }
  h
}
function main() -> int {
  let random = lcg_values(20000, 7);
  let sorted = merge_sort(random);
  let reversed = sorted.reverse();
  let dups: int[] = [];
  for (let v in random) { dups.push(v % 16); }
  let total = 0;
  for (let input in [random, sorted, reversed, dups]) {
    total = (total + checksum(merge_sort(input))) % 1000000007;
  }
  total
}

// Three-way quicksort with an explicit stack (from the native-bench quick_sort
// case): 1,024 integers in four orders (random, sorted, reversed, many
// duplicates), each copied, sorted in BAML code and serialized to JSON.
// setup() builds the four inputs once, untimed.
function setup() -> int[][] {
  let seed = 7;
  let random: int[] = [];
  let dups: int[] = [];
  for (let i = 0; i < 1024; i += 1) {
    seed = seed * 16807 % 2147483647;
    random.push(seed % 100000);
    dups.push(seed % 16);
  }
  let sorted: int[] = [];
  let reversed: int[] = [];
  for (let i = 0; i < 1024; i += 1) {
    sorted.push(i * 3);
    reversed.push((1023 - i) * 3);
  }
  [random, sorted, reversed, dups]
}

function quick_sort(values: int[]) -> int[] {
  let a: int[] = [];
  for (let v in values) { a.push(v); }
  let lows: int[] = [0];
  let highs: int[] = [a.length() - 1];
  let top = 1;
  while (top > 0) {
    top -= 1;
    let lo = lows[top];
    let hi = highs[top];
    if (lo < hi) {
      let pivot = a[lo + (hi - lo) / 2];
      let lt = lo;
      let i = lo;
      let gt = hi;
      while (i <= gt) {
        if (a[i] < pivot) {
          let v = a[lt]; a[lt] = a[i]; a[i] = v; lt += 1; i += 1;
        } else if (a[i] > pivot) {
          let v = a[gt]; a[gt] = a[i]; a[i] = v; gt -= 1;
        } else {
          i += 1;
        }
      }
      if (top == lows.length()) { lows.push(lo); highs.push(lt - 1); }
      else { lows[top] = lo; highs[top] = lt - 1; }
      top += 1;
      if (top == lows.length()) { lows.push(gt + 1); highs.push(hi); }
      else { lows[top] = gt + 1; highs[top] = hi; }
      top += 1;
    }
  }
  a
}

function run(inputs: int[][]) -> int {
  let check = 0;
  for (let input in inputs) {
    let out = baml.json.stringify(quick_sort(input));
    let h = 0;
    for (let c in out.to_code_points()) { h = (h * 31 + c) % 1000000007; }
    check = (check + h + out.length()) % 1000000007;
  }
  check
}

function main() -> int {
  run(setup())
}

