// A data-transformation job (from the native-bench json_aggregate case): build
// a 2,048-row JSON document, then 20 times decode it into typed classes,
// validate with a thrown error class, narrow an int | float union with match,
// group into a map, sort the keys and serialize the result.
class Row {
  account: string
  amount_cents: int | float
  active: bool
}

class Total {
  account: string
  total_cents: int
}

class Invalid {
  message: string
}

function rows_json(n: int) -> string {
  let seed = 11;
  let parts: string[] = [];
  for (let i = 0; i < n; i += 1) {
    seed = seed * 16807 % 2147483647;
    let account = (seed % 97).to_string();
    while (account.length() < 3) { account = "0" + account; }
    let amount = (seed % 100000).to_string();
    if (i % 5 == 0) { amount = amount + ".0"; }
    let active = if (seed % 7 != 0) { "true" } else { "false" };
    parts.push("{\"account\": \"acct-" + account + "\", \"amount_cents\": " + amount + ", \"active\": " + active + "}");
  }
  "[" + parts.join(", ") + "]"
}

function aggregate(raw: string) -> string {
  let rows = baml.json.decode<Row[]>(raw);
  let totals: map<string, int> = {};
  for (let row in rows) {
    if (!row.account.is_ascii()) { throw Invalid { message: "non-ASCII account" }; }
    let amount = match (row.amount_cents) {
      let n: int => n,
      let f: float => {
        if (f != f.floor() || f < 0.0 || f > 1000000.0) {
          throw Invalid { message: "invalid amount" };
        }
        f.itrunc()
      }
    };
    if (amount < 0 || amount > 1000000) { throw Invalid { message: "invalid amount" }; }
    if (row.active) { totals[row.account] = (totals.get(row.account) ?? 0) + amount; }
  }
  let accounts = totals.keys();
  accounts.sort();
  let output: Total[] = [];
  for (let account in accounts) {
    output.push(Total { account: account, total_cents: totals.get(account) ?? 0 });
  }
  baml.json.stringify(output)
}

function main() -> int {
  let raw = rows_json(2048);
  let check = 0;
  for (let i = 0; i < 20; i += 1) {
    let out = aggregate(raw) catch (_) { let _ => "invalid" };
    let h = 0;
    for (let c in out.to_code_points()) { h = (h * 31 + c) % 1000000007; }
    check = (check + h + out.length()) % 1000000007;
  }
  check
}

// Decode an NDJSON event log line by line into a typed class (B-1815): 2,000
// lines of about 400 bytes, each with optional fields that are null or absent
// and an `extra` object the class does not declare. The lines are built once
// in setup(); a job decodes every line with `baml.json.decode<Event>` and folds
// the fields into a checksum.
class Event {
  id: string
  session_id: string
  event_type: string
  role: string?
  content: string?
  tool_name: string?
  created_at: int
}

class Rng {
  seed: int
}

function draw(rng: Rng, n: int) -> int {
  rng.seed = rng.seed * 16807 % 2147483647;
  rng.seed % n
}

function setup() -> string[] {
  let rng = Rng { seed: 23 };
  let words = ["agent", "tool", "result", "latency", "token", "stream", "retry", "model", "prompt", "cache", "session", "vector"];
  let types = ["message", "tool_call", "tool_result", "status"];
  let roles = ["user", "assistant", "system"];
  let tools = ["search", "calculator", "browser", "shell"];
  let lines: string[] = [];
  for (let i = 0; i < 2000; i += 1) {
    let kind = draw(rng, 4);
    let parts: string[] = [];
    let length = 0;
    while (length < 290) {
      let word = words[draw(rng, 12)];
      parts.push(word);
      length += word.length() + 1;
    }
    let content = "\"" + parts.join(" ") + "\"";
    if (draw(rng, 3) == 0) { content = "\"" + parts.join(" ") + "\\n\\\"done\\\"\""; }
    if (kind == 3) { content = "null"; }
    let role = if (kind == 0) { "\"" + roles[draw(rng, 3)] + "\"" } else { "null" };
    let line = "{\"id\":\"evt_" + i.to_string() + "_" + draw(rng, 1000000).to_string() + "\"";
    line = line + ",\"session_id\":\"sess_" + draw(rng, 50).to_string() + "\"";
    line = line + ",\"event_type\":\"" + types[kind] + "\"";
    line = line + ",\"role\":" + role;
    line = line + ",\"content\":" + content;
    if (kind == 1 || kind == 2) { line = line + ",\"tool_name\":\"" + tools[draw(rng, 4)] + "\""; }
    line = line + ",\"extra\":{\"a\":[1,2,3],\"b\":\"z\"}";
    line = line + ",\"created_at\":" + (1700000000000 + i * 1000 + draw(rng, 1000)).to_string() + "}";
    lines.push(line);
  }
  lines
}

function run(lines: string[]) -> int {
  let check = 0;
  for (let line in lines) {
    let e = baml.json.decode<Event>(line);
    let h = e.created_at % 100000 + e.id.length() + e.session_id.length() + e.event_type.length();
    h += (e.role ?? "x").length() + (e.content ?? "nu").length() + (e.tool_name ?? "abc").length();
    check = (check + h) % 1000000007;
  }
  check
}

function main() -> int {
  run(setup())
}

// Serialize a provider request body: the class graph a chat client builds
// before each model call (the shape of OpenAI's Responses API), with message
// items mixing text and image parts, function-call replays, tools whose
// `parameters` are JSON Schema `json` values, and optional fields left null.
// The request is built once in setup(); a job writes it with
// `baml.json.stringify`, once as is and once with `omit_nulls`.
class InputText {
  type: string
  text: string
}

class InputImage {
  type: string
  image_url: string?
  file_id: string?
  detail: string?
}

type InputPart = InputText | InputImage

class MessageItem {
  role: string
  content: InputPart[]
}

class FunctionCallItem {
  type: string
  call_id: string
  name: string
  arguments: string
}

class FunctionCallOutputItem {
  type: string
  call_id: string
  output: string
}

type InputItem = MessageItem | FunctionCallItem | FunctionCallOutputItem

class FunctionTool {
  type: string
  name: string
  description: string
  parameters: json
  strict: bool
}

class Reasoning {
  effort: string?
  summary: string?
}

class Request {
  model: string
  instructions: string?
  input: InputItem[]
  tools: FunctionTool[]
  tool_choice: string?
  temperature: float?
  top_p: float?
  max_output_tokens: int
  parallel_tool_calls: bool
  reasoning: Reasoning?
  metadata: map<string, string>
  store: bool
  user: string?
  stream: bool
}

class Rng {
  seed: int
}

function draw(rng: Rng, n: int) -> int {
  rng.seed = rng.seed * 16807 % 2147483647;
  rng.seed % n
}

function sentence(rng: Rng, words: string[], count: int) -> string {
  let parts: string[] = [];
  for (let i = 0; i < count; i += 1) { parts.push(words[draw(rng, words.length())]); }
  parts.join(" ")
}

function tool_schema(rng: Rng, words: string[], fields: int) -> json {
  let properties: map<string, json> = {};
  let required: json[] = [];
  for (let f = 0; f < fields; f += 1) {
    let name = words[draw(rng, words.length())] + "_" + f.to_string();
    let kind = draw(rng, 4);
    if (kind == 0) {
      properties[name] = { "type": "string", "description": sentence(rng, words, 6) };
    } else if (kind == 1) {
      properties[name] = { "type": "integer", "minimum": 0, "maximum": 1000 + draw(rng, 9000) };
    } else if (kind == 2) {
      properties[name] = { "type": "array", "items": { "type": "string", "enum": ["low", "medium", "high"] } };
    } else {
      properties[name] = {
        "type": "object",
        "properties": { "lat": { "type": "number" }, "lng": { "type": "number" } },
        "required": ["lat", "lng"],
        "additionalProperties": false,
      };
    }
    if (draw(rng, 3) != 0) { required.push(name); }
  }
  { "type": "object", "properties": properties, "required": required, "additionalProperties": false }
}

function setup() -> Request {
  let rng = Rng { seed: 29 };
  let words = ["weather", "forecast", "city", "units", "latency", "budget", "invoice", "customer", "order", "status", "refund", "search", "query", "limit", "region", "timezone"];
  let input: InputItem[] = [];
  for (let i = 0; i < 24; i += 1) {
    let kind = draw(rng, 4);
    if (kind < 2) {
      let parts: InputPart[] = [];
      let count = 1 + draw(rng, 3);
      for (let p = 0; p < count; p += 1) {
        if (draw(rng, 4) == 0) {
          parts.push(InputImage {
            type: "input_image",
            image_url: "https://example.com/images/" + draw(rng, 100000).to_string() + ".png",
            file_id: null,
            detail: if (draw(rng, 2) == 0) { "auto" } else { null },
          });
        } else {
          parts.push(InputText { type: "input_text", text: sentence(rng, words, 12 + draw(rng, 30)) });
        }
      }
      input.push(MessageItem { role: if (kind == 0) { "user" } else { "assistant" }, content: parts });
    } else if (kind == 2) {
      let call = "call_" + draw(rng, 1000000).to_string();
      input.push(FunctionCallItem {
        type: "function_call",
        call_id: call,
        name: words[draw(rng, words.length())],
        arguments: "{\"query\":\"" + sentence(rng, words, 3) + "\",\"limit\":" + draw(rng, 50).to_string() + "}",
      });
    } else {
      input.push(FunctionCallOutputItem {
        type: "function_call_output",
        call_id: "call_" + draw(rng, 1000000).to_string(),
        output: sentence(rng, words, 20),
      });
    }
  }
  let tools: FunctionTool[] = [];
  for (let t = 0; t < 8; t += 1) {
    tools.push(FunctionTool {
      type: "function",
      name: "tool_" + words[draw(rng, words.length())] + "_" + t.to_string(),
      description: sentence(rng, words, 10),
      parameters: tool_schema(rng, words, 2 + draw(rng, 5)),
      strict: draw(rng, 2) == 0,
    });
  }
  Request {
    model: "gpt-5.1-mini",
    instructions: null,
    input: input,
    tools: tools,
    tool_choice: "auto",
    temperature: 0.7,
    top_p: null,
    max_output_tokens: 4096,
    parallel_tool_calls: true,
    reasoning: Reasoning { effort: "low", summary: null },
    metadata: { "session": "sess_" + draw(rng, 1000).to_string(), "trace": "tr_" + draw(rng, 100000).to_string() },
    store: false,
    user: null,
    stream: true,
  }
}

function run(request: Request) -> int {
  baml.json.stringify(request).length() * 3 + baml.json.stringify(request, omit_nulls = true).length()
}

function main() -> int {
  run(setup())
}

// Read typed values out of a large parsed document: a 1 MB JSON array of
// 3,200 user records is parsed once in setup(); a job runs 400 rounds of
// `baml.json.path<T>` reads into it (an int, a string, a nested list element,
// an optional field) and decodes one whole record with `baml.json.to<User>`.
class Address {
  street: string
  city: string
  zip: string
}

class Order {
  sku: string
  qty: int
  price: float
}

class User {
  id: int
  name: string
  email: string
  age: int
  active: bool
  score: float
  tags: string[]
  address: Address
  orders: Order[]
  manager_id: int?
}

class Tree {
  doc: json
  users: json[]
}

class Rng {
  seed: int
}

function draw(rng: Rng, n: int) -> int {
  rng.seed = rng.seed * 16807 % 2147483647;
  rng.seed % n
}

function quoted(s: string) -> string {
  "\"" + s + "\""
}

function setup() -> Tree {
  let rng = Rng { seed: 37 };
  let words = ["alpha", "bravo", "charlie", "delta", "echo", "foxtrot", "golf", "hotel", "india", "juliet", "kilo", "lima"];
  let users: string[] = [];
  for (let i = 0; i < 3200; i += 1) {
    let tags: string[] = [];
    let tag_count = 1 + draw(rng, 4);
    for (let t = 0; t < tag_count; t += 1) { tags.push(quoted(words[draw(rng, 12)])); }
    let orders: string[] = [];
    let order_count = 1 + draw(rng, 3);
    for (let o = 0; o < order_count; o += 1) {
      let sku = quoted("sku-" + draw(rng, 100000).to_string());
      let price = draw(rng, 1000).to_string() + "." + draw(rng, 100).to_string();
      orders.push("{\"sku\":" + sku + ",\"qty\":" + (1 + draw(rng, 9)).to_string() + ",\"price\":" + price + "}");
    }
    let name = words[draw(rng, 12)] + "_" + i.to_string();
    let street = (1 + draw(rng, 999)).to_string() + " " + words[draw(rng, 12)] + " street";
    let address = "{\"street\":" + quoted(street) + ",\"city\":" + quoted(words[draw(rng, 12)] + "ville") + ",\"zip\":" + quoted((10000 + draw(rng, 89999)).to_string()) + "}";
    let manager = if (draw(rng, 3) == 0) { "null" } else { draw(rng, 3200).to_string() };
    let user = "{\"id\":" + i.to_string() + ",\"name\":" + quoted(name) + ",\"email\":" + quoted(name + "@example.com");
    user = user + ",\"age\":" + (18 + draw(rng, 60)).to_string() + ",\"active\":" + (if (draw(rng, 4) == 0) { "false" } else { "true" });
    user = user + ",\"score\":" + draw(rng, 100).to_string() + "." + draw(rng, 1000).to_string();
    user = user + ",\"tags\":[" + tags.join(",") + "],\"address\":" + address + ",\"orders\":[" + orders.join(",") + "],\"manager_id\":" + manager + "}";
    users.push(user);
  }
  let doc = baml.json.parse("{\"meta\":{\"version\":3,\"count\":3200},\"users\":[" + users.join(",") + "]}");
  Tree { doc: doc, users: baml.json.path<json[]>(doc, ".users") }
}

function run(tree: Tree) -> int {
  let rng = Rng { seed: 41 };
  let check = 0;
  for (let k = 0; k < 400; k += 1) {
    let base = ".users[" + draw(rng, 3200).to_string() + "]";
    check += baml.json.path<int>(tree.doc, base + ".age");
    check += baml.json.path<string>(tree.doc, base + ".address.city").length();
    check += baml.json.path<int>(tree.doc, base + ".orders[0].qty");
    check += baml.json.path<int?>(tree.doc, base + ".manager_id") ?? 7;
    let user = baml.json.to<User>(tree.users[draw(rng, 3200)]);
    check += user.tags.length() * 3 + user.orders.length() + user.name.length() + (if (user.active) { 1 } else { 0 });
    check = check % 1000000007;
  }
  check
}

function main() -> int {
  run(setup())
}

